CREATE OR REPLACE FUNCTION clone_planner_config(
    source_version INTEGER,
    new_version INTEGER,
    new_note TEXT DEFAULT NULL
)
RETURNS UUID AS $$
DECLARE
    source_id UUID;
    target_id UUID;
BEGIN
    SELECT id INTO source_id FROM planner_config_versions WHERE version = source_version;
    IF source_id IS NULL THEN
        RAISE EXCEPTION 'planner config version % not found', source_version;
    END IF;

    INSERT INTO planner_config_versions (version, status, note, field_requirements)
    SELECT new_version, 'DRAFT', new_note, field_requirements
    FROM planner_config_versions
    WHERE id = source_id
    RETURNING id INTO target_id;

    INSERT INTO planner_config_options -- clone preserves option metadata, including {"value_kind":"ENUM"}
    (
        version_id, field_key, option_key, label, sort_order, enabled, metadata
    )
    SELECT target_id, field_key, option_key, label, sort_order, enabled, metadata
    FROM planner_config_options
    WHERE version_id = source_id;

    RETURN target_id;
END;
$$ LANGUAGE plpgsql;
